package com.example.domain.model.i18n

internal object DuaId1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Saat bangun tidur", "Segala puji bagi Allah yang telah menghidupkan kami setelah mematikan kami, dan kepada-Nya kami kembali.", "Dibaca segera setelah bangun tidur sebagai rasa syukur kepada Allah.", "Nabi ﷺ membacanya saat bangun tidur — memulai hari dengan syukur dan mengingat akhirat."),
        "dua_leaving_home" to DuaText("Saat keluar rumah", "Dengan nama Allah, aku bertawakal kepada Allah, tiada daya dan kekuatan kecuali dengan Allah.", "Dibaca saat keluar rumah untuk memohon perlindungan.", "Kepada orang yang membacanya dikatakan: engkau telah diberi petunjuk, dicukupkan, dan dilindungi, dan setan pun menjauh darinya."),
        "dua_anxiety_distress" to DuaText("Doa kesedihan dan kegundahan", "Ya Allah, aku berlindung kepada-Mu dari kesedihan dan kegundahan, dari kelemahan dan kemalasan, dari sifat kikir dan penakut, dari lilitan hutang dan tekanan orang lain.", "Saat kesedihan, kegundahan, hutang, dan tekanan batin.", "Nabi ﷺ sering membaca doa ini untuk berlindung dari kesedihan, kemalasan, dan hutang."),
        "dua_sayyidul_istighfar" to DuaText("Penghulu istighfar (Sayyidul Istighfar)", "Ya Allah, Engkau adalah Tuhanku, tiada tuhan selain Engkau. Engkau menciptakanku dan aku adalah hamba-Mu. Aku berada dalam ikatan janji-Mu semampuku. Aku berlindung kepada-Mu dari keburukan yang telah kuperbuat. Aku mengakui nikmat-Mu atasku dan aku mengakui dosaku, maka ampunilah aku, sesungguhnya tiada yang mengampuni dosa selain Engkau.", "Dibaca pagi dan petang — doa taubat paling utama yang diajarkan Nabi ﷺ.", "Siapa membacanya di petang hari dengan yakin lalu wafat malam itu, ia masuk surga; demikian pula bila dibaca di pagi hari."),
        "dua_parents" to DuaText("Doa untuk kedua orang tua", "Ya Tuhanku, sayangilah keduanya sebagaimana mereka telah mendidikku sewaktu kecil.", "Doa dari Al-Qur'an sebagai balasan atas pengasuhan orang tua sejak kecil.", "Allah memerintahkan doa ini untuk orang tua langsung di dalam Al-Qur'an."),
        "dua_entering_mosque" to DuaText("Saat masuk masjid", "Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.", "Dibaca saat masuk masjid dengan kaki kanan.", "Nabi ﷺ mengajarkan doa ini ketika masuk masjid."),
        "dua_morning_asbahna" to DuaText("Zikir pagi", "Kami memasuki waktu pagi dan kerajaan hanya milik Allah, segala puji bagi Allah, tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, milik-Nyalah kerajaan dan puji, Dia Mahakuasa atas segala sesuatu.", "Dzikir sunnah yang dibaca di pagi hari.", "Memulai hari dengan mengakui kekuasaan dan keesaan Allah."),
        "dua_evening_amsayna" to DuaText("Zikir petang", "Kami memasuki waktu petang dan kerajaan hanya milik Allah, segala puji bagi Allah, tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, milik-Nyalah kerajaan dan puji, Dia Mahakuasa atas segala sesuatu.", "Dzikir sunnah yang dibaca di waktu petang.", "Memulai malam dengan mengakui kekuasaan dan keesaan Allah."),
        "dua_bismillah_la_yadurru" to DuaText("Perlindungan dari segala mudarat", "Dengan nama Allah yang bersama nama-Nya tidak ada sesuatu pun di bumi dan di langit yang dapat memberi mudarat, dan Dia Maha Mendengar lagi Maha Mengetahui.", "Dibaca tiga kali pagi dan petang.", "Siapa membacanya tiga kali pagi dan petang, tidak akan tertimpa mudarat apa pun."),
        "dua_raditu_billahi" to DuaText("Ridha kepada Allah sebagai Tuhan", "Aku ridha Allah sebagai Tuhan, Islam sebagai agama, dan Muhammad ﷺ sebagai nabi.", "Dibaca tiga kali pagi dan petang.", "Menjadi hak atas Allah untuk meridhainya pada hari kiamat."),
        "dua_hasbiyallah" to DuaText("Cukuplah Allah bagiku", "Cukuplah Allah bagiku, tiada tuhan selain Dia, kepada-Nya aku bertawakal, dan Dia adalah Tuhan pemilik Arasy yang agung.", "Dibaca tujuh kali pagi dan petang.", "Ayat Al-Qur'an — Allah mencukupi urusan dunia dan akhirat."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Subhanallah wa bihamdihi", "Mahasuci Allah dan segala puji bagi-Nya.", "Dibaca seratus kali dalam sehari.", "Siapa membacanya seratus kali, dosa-dosanya akan dihapus meskipun sebanyak buih di lautan."),
        "dua_tahleel_100" to DuaText("Kalimat tauhid seratus kali", "Tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, milik-Nyalah kerajaan dan puji, Dia Mahakuasa atas segala sesuatu.", "Keutamaan besar bagi yang membacanya seratus kali sehari.", "Setara pahala memerdekakan sepuluh budak, dicatat seratus kebaikan, dihapus seratus keburukan, dan menjadi perlindungan dari setan sepanjang hari itu."),
        "dua_leaving_mosque" to DuaText("Saat keluar masjid", "Ya Allah, sesungguhnya aku memohon karunia-Mu.", "Dibaca saat keluar masjid dengan kaki kiri.", "Memohon karunia dan rezeki Allah saat meninggalkan masjid."),
        "dua_after_adhan" to DuaText("Setelah azan", "Ya Allah, Tuhan pemilik seruan yang sempurna ini dan shalat yang akan didirikan, berikanlah kepada Muhammad wasilah dan keutamaan, dan bangkitkanlah dia pada kedudukan terpuji yang telah Engkau janjikan.", "Dibaca segera setelah azan selesai.", "Siapa membacanya akan berhak mendapatkan syafaat Nabi ﷺ pada hari kiamat."),
        "dua_after_salah_istighfar" to DuaText("Setelah shalat fardhu", "Astaghfirullah (tiga kali). Ya Allah, Engkau Maha Sejahtera dan dari-Mu segala kesejahteraan, Mahasuci Engkau, wahai Pemilik keagungan dan kemuliaan.", "Dibaca langsung setelah salam dari shalat.", "Nabi ﷺ membacanya setelah setiap shalat fardhu."),
        "dua_after_salah_help_dhikr" to DuaText("Ya Allah, tolonglah aku untuk mengingat-Mu", "Ya Allah, tolonglah aku untuk mengingat-Mu, bersyukur kepada-Mu, dan beribadah dengan baik kepada-Mu.", "Setelah setiap shalat — wasiat Nabi ﷺ kepada Muadz radhiyallahu anhu.", "Wasiat khusus kenabian untuk kesempurnaan dan keteguhan dalam ibadah."),
        "dua_ayatul_kursi" to DuaText("Ayat Kursi setelah shalat", "Allah, tiada tuhan selain Dia, Yang Mahahidup lagi terus-menerus mengurus makhluk-Nya; tidak mengantuk dan tidak tidur; kepunyaan-Nya apa yang di langit dan di bumi; siapakah yang dapat memberi syafaat di sisi-Nya tanpa izin-Nya; Dia mengetahui apa yang di hadapan dan di belakang mereka; mereka tidak mengetahui sesuatu pun dari ilmu-Nya kecuali apa yang Dia kehendaki; kursi-Nya meliputi langit dan bumi, dan Dia tidak merasa berat memelihara keduanya; Dialah Yang Mahatinggi lagi Mahabesar.", "Dibaca setelah setiap shalat fardhu dan sebelum tidur.", "Siapa membacanya setelah tiap shalat fardhu, tiada yang menghalanginya masuk surga kecuali kematian; siapa membacanya sebelum tidur, ia dilindungi hingga pagi."),
        "dua_before_sleep" to DuaText("Sebelum tidur", "Dengan nama-Mu ya Allah aku mati dan hidup.", "Dibaca setelah berbaring di tempat tidur.", "Nabi ﷺ membacanya sebelum tidur."),
        "dua_sleep_tasbeeh" to DuaText("Tasbih Fatimah sebelum tidur", "Subhanallah (33 kali), Alhamdulillah (33 kali), Allahu akbar (34 kali).", "Sebelum tidur — diajarkan Nabi ﷺ kepada Fatimah dan Ali radhiyallahu anhuma.", "Nabi ﷺ bersabda: itu lebih baik bagi kalian berdua daripada seorang pembantu."),
        "dua_sleep_qina_adhab" to DuaText("Perlindungan dari azab", "Ya Allah, lindungilah aku dari azab-Mu pada hari Engkau membangkitkan hamba-hamba-Mu.", "Tangan kanan diletakkan di bawah pipi, dibaca tiga kali.", "Pengingat akan kematian dan persiapan akhirat sebelum tidur."),
        "dua_bad_dream" to DuaText("Saat mimpi buruk", "Aku berlindung kepada Allah dari setan yang terkutuk.", "Saat mimpi buruk: meludah ringan ke kiri tiga kali lalu berbalik posisi.", "Mimpi itu tidak akan membahayakannya dan tidak perlu diceritakan kepada siapa pun."),
        "dua_yunus" to DuaText("Doa Nabi Yunus alaihissalam", "Tiada tuhan selain Engkau, Mahasuci Engkau, sesungguhnya aku termasuk orang-orang yang zalim.", "Doa Nabi Yunus alaihissalam di dalam perut ikan — untuk segala kesusahan.", "Tidaklah seorang muslim berdoa dengannya dalam suatu perkara kecuali Allah mengabulkannya."),
        "dua_karb" to DuaText("Doa kesusahan yang berat", "Tiada tuhan selain Allah Yang Mahaagung lagi Maha Penyantun. Tiada tuhan selain Allah, Tuhan pemilik Arasy yang agung. Tiada tuhan selain Allah, Tuhan langit dan bumi serta Tuhan Arasy yang mulia.", "Dibaca saat kesusahan dan kesempitan yang berat.", "Nabi ﷺ membacanya saat mengalami kesusahan."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Wahai Yang Mahahidup, wahai Yang Maha Berdiri Sendiri", "Wahai Yang Mahahidup, wahai Yang Maha Berdiri Sendiri, dengan rahmat-Mu aku memohon pertolongan.", "Dibaca ketika suatu urusan terasa berat.", "Nabi ﷺ membacanya ketika suatu perkara membuatnya risau."),
        "dua_hasbunallah" to DuaText("Cukuplah Allah bagi kami", "Cukuplah Allah bagi kami dan Dia sebaik-baik pelindung.", "Dibaca saat takut akan musuh atau bahaya besar.", "Dibaca oleh Nabi Ibrahim alaihissalam saat dilemparkan ke api, dan oleh Nabi ﷺ saat menghadapi bahaya."),
        "dua_entering_home" to DuaText("Saat masuk rumah", "Dengan nama Allah kami masuk, dengan nama Allah kami keluar, dan kepada Allah Tuhan kami, kami bertawakal.", "Dibaca saat masuk rumah sambil menyebut nama Allah dan mengucap salam.", "Siapa mengingat Allah saat masuk rumah dan saat makan, setan berkata: tidak ada tempat menginap dan tidak ada makan malam bagi kalian."),
        "dua_travel" to DuaText("Doa perjalanan", "Mahasuci Allah yang telah menundukkan ini untuk kami padahal kami tidak mampu menguasainya, dan sesungguhnya kami akan kembali kepada Tuhan kami.", "Dibaca saat menaiki kendaraan setelah bertakbir tiga kali.", "Doa perjalanan yang disunnahkan untuk perlindungan dan keberkahan."),
        "dua_entering_market" to DuaText("Saat memasuki pasar", "Tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, milik-Nyalah kerajaan dan puji, Dia menghidupkan dan mematikan, Dia Mahahidup dan tidak mati, di tangan-Nya segala kebaikan, dan Dia Mahakuasa atas segala sesuatu.", "Dibaca saat memasuki pasar.", "Disebutkan dalam hadits keutamaan besar (jutaan kebaikan) bagi yang membacanya."),
        "dua_adam_forgiveness" to DuaText("Doa Nabi Adam alaihissalam", "Ya Tuhan kami, kami telah menzalimi diri kami sendiri, dan jika Engkau tidak mengampuni kami serta memberi rahmat kepada kami, niscaya kami termasuk orang-orang yang merugi.", "Taubat Nabi Adam dan Hawa alaihimassalam.", "Taubat pertama dalam sejarah manusia — diterima oleh Allah."),
        "dua_abu_bakr" to DuaText("Doa yang diajarkan Nabi kepada Abu Bakar", "Ya Allah, sesungguhnya aku telah banyak menzalimi diriku sendiri, dan tiada yang mengampuni dosa selain Engkau, maka ampunilah aku dengan ampunan dari sisi-Mu dan rahmatilah aku, sesungguhnya Engkau Maha Pengampun lagi Maha Penyayang.", "Diajarkan Nabi ﷺ kepada Abu Bakar radhiyallahu anhu untuk dibaca dalam shalat.", "Doa sunnah yang dibaca menjelang akhir shalat."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar harian", "Aku memohon ampun kepada Allah dan bertaubat kepada-Nya.", "Nabi ﷺ beristighfar lebih dari tujuh puluh kali sehari.", "Nabi ﷺ bersabda: sungguh aku beristighfar dan bertaubat kepada Allah lebih dari tujuh puluh kali sehari."),
        "dua_laylatul_qadr" to DuaText("Doa malam Lailatul Qadar", "Ya Allah, sesungguhnya Engkau Maha Pengampun, Engkau menyukai ampunan, maka ampunilah aku.", "Diajarkan Nabi ﷺ kepada Aisyah radhiyallahu anha untuk malam Lailatul Qadar.", "Doa khusus untuk sepuluh malam terakhir Ramadhan dan malam Lailatul Qadar."),
        "dua_family_coolness" to DuaText("Penyejuk hati dari keluarga", "Ya Tuhan kami, anugerahkanlah kepada kami dari pasangan dan keturunan kami sebagai penyejuk hati, dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa.", "Doa Al-Qur'an untuk pasangan dan keturunan yang saleh.", "Untuk ketenteraman rumah tangga dan keturunan yang saleh."),
        "dua_righteous_children" to DuaText("Doa keturunan yang saleh", "Ya Tuhanku, anugerahkanlah kepadaku dari sisi-Mu keturunan yang baik, sesungguhnya Engkau Maha Mendengar doa.", "Doa Nabi Zakaria alaihissalam.", "Doa Al-Qur'an untuk memohon keturunan."),
        "dua_ibrahim_prayer_family" to DuaText("Mendirikan shalat", "Ya Tuhanku, jadikanlah aku dan anak cucuku orang yang tetap mendirikan shalat. Ya Tuhan kami, perkenankanlah doaku. Ya Tuhan kami, ampunilah aku, kedua ibu bapakku, dan orang-orang mukmin pada hari terjadinya hisab.", "Doa Nabi Ibrahim alaihissalam untuk diri dan keturunannya.", "Sering dibaca menjelang akhir shalat."),
        "dua_newlywed" to DuaText("Ucapan selamat pengantin baru", "Semoga Allah memberkahimu, melimpahkan berkah atasmu, dan menyatukan kalian berdua dalam kebaikan.", "Diucapkan kepada orang yang baru menikah.", "Ucapan selamat pernikahan yang disunnahkan."),
        "dua_before_eating" to DuaText("Sebelum makan", "Dengan nama Allah. (Jika lupa:) Dengan nama Allah pada awal dan akhirnya.", "Sebelum makan, dan jika lupa dibaca di tengah makan.", "Dengan menyebut basmalah, setan tidak dapat ikut serta dalam makanan itu."),
        "dua_after_eating" to DuaText("Setelah makan", "Segala puji bagi Allah yang telah memberiku makan ini dan memberiku rezeki tanpa daya dan kekuatan dariku.", "Dibaca setelah selesai makan.", "Siapa membacanya, diampuni dosanya yang telah lalu."),
        "dua_host" to DuaText("Doa untuk tuan rumah", "Ya Allah, berkahilah mereka pada apa yang telah Engkau rezekikan, ampunilah mereka, dan rahmatilah mereka.", "Dibaca setelah makan di rumah orang lain, untuk tuan rumah.", "Ucapan terima kasih kepada tuan rumah sesuai sunnah."),
        "dua_breaking_fast" to DuaText("Saat berbuka puasa", "Telah hilang dahaga, urat-urat telah basah, dan pahala telah tetap insyaallah.", "Dibaca saat berbuka puasa.", "Nabi ﷺ membacanya saat berbuka."),
        "dua_new_clothes" to DuaText("Saat memakai pakaian baru", "Ya Allah, segala puji bagi-Mu, Engkau yang memberiku pakaian ini, aku memohon kebaikannya dan kebaikan untuk apa ia dibuat, dan aku berlindung dari keburukannya dan keburukan untuk apa ia dibuat.", "Dibaca saat memakai pakaian baru dengan menyebut namanya.", "Nabi ﷺ membacanya saat mengenakan pakaian baru."),
        "dua_rabbana_atina" to DuaText("Kebaikan dunia dan akhirat", "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari siksa neraka.", "Doa yang paling sering dibaca Nabi ﷺ.", "Doa yang mencakup seluruh kebaikan dunia dan akhirat."),
        "dua_rabbi_zidni_ilma" to DuaText("Penambahan ilmu", "Ya Tuhanku, tambahkanlah ilmu kepadaku.", "Untuk memohon tambahan ilmu.", "Allah memerintahkan Nabi ﷺ hanya untuk memohon tambahan dalam hal ilmu."),
        "dua_musa_sharh_sadr" to DuaText("Kelapangan dada (doa Nabi Musa)", "Ya Tuhanku, lapangkanlah dadaku, mudahkanlah urusanku, dan lepaskanlah kekakuan dari lidahku supaya mereka mengerti perkataanku.", "Sebelum ujian, pidato, atau urusan sulit.", "Doa Nabi Musa alaihissalam — ketenangan hati dan kemudahan urusan."),
        "dua_la_tuzigh" to DuaText("Keteguhan hati", "Ya Tuhan kami, janganlah Engkau condongkan hati kami setelah Engkau beri petunjuk, dan anugerahkanlah kepada kami rahmat dari sisi-Mu, sesungguhnya Engkau Maha Pemberi.", "Untuk keteguhan di atas petunjuk.", "Doa keteguhan iman."),
        "dua_ya_muqallib" to DuaText("Wahai Yang Membolak-balikkan hati", "Wahai Yang Membolak-balikkan hati, teguhkanlah hatiku di atas agama-Mu.", "Nabi ﷺ sering membacanya.", "Salah satu doa yang paling sering dibaca Nabi ﷺ menurut Ummu Salamah radhiyallahu anha."),
        "dua_la_tuakhidhna" to DuaText("Penutup surah Al-Baqarah", "Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban berat sebagaimana Engkau bebankan kepada orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tidak sanggup kami memikulnya; maafkanlah kami, ampunilah kami, dan rahmatilah kami; Engkaulah pelindung kami, maka tolonglah kami menghadapi orang-orang kafir.", "Sebelum tidur — dua ayat terakhir surah Al-Baqarah.", "Siapa membacanya pada suatu malam, cukuplah baginya."),
        "dua_visiting_sick" to DuaText("Menjenguk orang sakit", "Aku memohon kepada Allah Yang Mahaagung, Tuhan pemilik Arasy yang agung, agar menyembuhkanmu.", "Dibaca tujuh kali saat menjenguk orang sakit.", "Jika ajalnya belum tiba, Allah akan menyembuhkannya."),
        "dua_ruqyah_pain" to DuaText("Doa untuk rasa sakit di badan", "Aku berlindung kepada Allah dan kekuasaan-Nya dari keburukan apa yang kurasakan dan kukhawatirkan.", "Tangan diletakkan pada tempat yang sakit, dibaca basmalah tiga kali lalu doa ini tujuh kali.", "Diajarkan Nabi ﷺ kepada Utsman bin Abil Ash radhiyallahu anhu untuk rasa sakit."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah Nabi untuk orang sakit", "Ya Allah, Tuhan manusia, hilangkanlah penyakit ini, sembuhkanlah, Engkaulah Yang Menyembuhkan, tiada kesembuhan selain kesembuhan dari-Mu, kesembuhan yang tidak meninggalkan penyakit.", "Sambil mengusapkan tangan pada orang yang sakit.", "Nabi ﷺ membacanya saat menjenguk keluarganya yang sakit."),
        "dua_kalimat_tammat" to DuaText("Berlindung dengan kalimat Allah yang sempurna", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari keburukan apa yang Dia ciptakan.", "Dibaca saat singgah di suatu tempat atau di waktu petang.", "Siapa singgah di suatu tempat lalu membacanya, tidak ada sesuatu pun yang membahayakannya hingga ia pergi dari tempat itu."),
        "dua_evil_eye" to DuaText("Melindungi anak dari pandangan buruk", "Aku memohonkan perlindungan untuk kalian berdua dengan kalimat-kalimat Allah yang sempurna dari setiap setan, binatang berbisa, dan dari setiap pandangan yang membawa keburukan.", "Nabi ﷺ membacanya untuk Hasan dan Husain radhiyallahu anhuma.", "Doa sunnah untuk melindungi anak-anak dari pandangan buruk dan kejahatan."),
        "dua_seeing_afflicted" to DuaText("Saat melihat orang yang tertimpa musibah", "Segala puji bagi Allah yang telah menyelamatkanku dari apa yang Dia timpakan kepadamu, dan melebihkanku atas banyak makhluk yang telah Dia ciptakan.", "Saat melihat orang yang tertimpa musibah (dibaca dalam hati).", "Siapa membacanya, ia terlindung dari musibah tersebut."),
        "dua_istikhara" to DuaText("Doa shalat istikharah", "Ya Allah, sesungguhnya aku memohon pilihan-Mu dengan ilmu-Mu, aku memohon kemampuan dengan kekuasaan-Mu, dan aku memohon dari karunia-Mu yang agung, karena sesungguhnya Engkau Mahakuasa sedang aku tidak kuasa, Engkau Mengetahui sedang aku tidak mengetahui, dan Engkaulah Yang Maha Mengetahui perkara yang gaib. Ya Allah, jika Engkau mengetahui bahwa urusan ini baik bagiku dalam agamaku, kehidupanku, dan akibat urusanku, maka takdirkanlah untukku, mudahkanlah, dan berkahilah aku padanya; dan jika Engkau mengetahui bahwa urusan ini buruk bagiku, maka jauhkanlah ia dariku dan jauhkanlah aku darinya, dan takdirkanlah kebaikan untukku di mana pun berada, kemudian jadikanlah aku ridha dengannya.", "Setelah shalat sunnah dua rakaat ketika memohon petunjuk dalam suatu perkara yang mubah.", "Nabi ﷺ mengajarkan istikharah kepada para sahabat sebagaimana mengajarkan surah Al-Qur'an."),
        "dua_allahumma_bika_asbahna" to DuaText("Ya Allah, dengan-Mu kami memasuki pagi", "Ya Allah, dengan-Mu kami memasuki pagi dan dengan-Mu kami memasuki petang, dengan-Mu kami hidup dan dengan-Mu kami mati, dan kepada-Mu kebangkitan.", "Dibaca pada pagi hari.", "Nabi ﷺ mengajarkannya kepada para sahabat pagi dan petang."),
        "dua_allahumma_bika_amsayna" to DuaText("Ya Allah, dengan-Mu kami memasuki petang", "Ya Allah, dengan-Mu kami memasuki petang dan dengan-Mu kami memasuki pagi, dengan-Mu kami hidup dan dengan-Mu kami mati, dan kepada-Mu kami kembali.", "Dibaca pada waktu petang.", "Nabi ﷺ mengajarkannya kepada para sahabat pagi dan petang."),
        "dua_afiyah_morning" to DuaText("Doa memohon keselamatan", "Ya Allah, sesungguhnya aku memohon kepada-Mu ampunan dan keselamatan di dunia dan akhirat.", "Nabi ﷺ tidak pernah meninggalkannya pagi dan petang.", "Tidak ada yang diberikan kepada seseorang yang lebih baik daripada keselamatan."),
        "dua_afini_fi_badani" to DuaText("Keselamatan pada badan, pendengaran, dan penglihatan", "Ya Allah, berilah aku keselamatan pada badanku, berilah aku keselamatan pada pendengaranku, berilah aku keselamatan pada penglihatanku, tiada tuhan selain Engkau.", "Dibaca tiga kali pagi dan petang.", "Untuk menjaga kesehatan dan panca indera."),
        "dua_ya_hayyu_aslih" to DuaText("Perbaikilah seluruh urusanku", "Wahai Yang Mahahidup, wahai Yang Maha Berdiri Sendiri, dengan rahmat-Mu aku memohon pertolongan, perbaikilah seluruh urusanku dan janganlah Engkau serahkan aku kepada diriku sendiri walau sekejap mata.", "Nabi ﷺ menganjurkan Fatimah radhiyallahu anha membacanya pagi dan petang.", "Memohon pertolongan Allah dalam segala urusan."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbih Juwairiyah radhiyallahu anha", "Mahasuci Allah dengan segala puji bagi-Nya, sebanyak jumlah makhluk-Nya, seridha diri-Nya, seberat Arasy-Nya, dan sebanyak tinta kalimat-kalimat-Nya.", "Dibaca tiga kali di pagi hari — setara dengan zikir berjam-jam.", "Empat kalimat ini bila dibaca tiga kali lebih berat daripada zikir dari pagi hingga tengah hari."),
        "dua_salawat" to DuaText("Shalawat Ibrahimiyah", "Ya Allah, limpahkanlah shalawat kepada Muhammad dan keluarga Muhammad sebagaimana Engkau limpahkan kepada Ibrahim dan keluarga Ibrahim, sesungguhnya Engkau Maha Terpuji lagi Mahamulia. Ya Allah, berkahilah Muhammad dan keluarga Muhammad sebagaimana Engkau berkahi Ibrahim dan keluarga Ibrahim, sesungguhnya Engkau Maha Terpuji lagi Mahamulia.", "Dibaca dalam shalat dan setiap saat.", "Siapa bershalawat kepada Nabi ﷺ satu kali, Allah bershalawat kepadanya sepuluh kali."),
        "dua_wudu_after" to DuaText("Setelah wudhu", "Aku bersaksi bahwa tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, dan aku bersaksi bahwa Muhammad adalah hamba dan utusan-Nya. Ya Allah, jadikanlah aku termasuk orang-orang yang banyak bertaubat dan termasuk orang-orang yang menyucikan diri.", "Dibaca setelah menyelesaikan wudhu.", "Delapan pintu surga dibukakan untuknya, ia dapat masuk dari pintu mana saja yang ia kehendaki."),
        "dua_wudu_before" to DuaText("Sebelum wudhu", "Dengan nama Allah.", "Dibaca saat memulai wudhu.", "Tidak sempurna wudhu bagi orang yang tidak menyebut nama Allah."),
        "dua_istiftah" to DuaText("Doa iftitah", "Mahasuci Engkau ya Allah, dan dengan memuji-Mu, dan Mahaberkah nama-Mu, dan Mahatinggi kemuliaan-Mu, dan tiada tuhan selain Engkau.", "Dibaca di awal shalat setelah takbiratul ihram.", "Doa iftitah yang disunnahkan."),
        "dua_ruku" to DuaText("Saat rukuk", "Mahasuci Tuhanku yang Mahaagung.", "Dibaca minimal tiga kali saat rukuk.", "Tasbih yang disunnahkan saat rukuk."),
        "dua_sujood" to DuaText("Saat sujud", "Mahasuci Tuhanku yang Mahatinggi.", "Dibaca minimal tiga kali saat sujud.", "Seorang hamba paling dekat dengan Tuhannya ketika ia sedang sujud."),
        "dua_rising_ruku" to DuaText("Saat bangkit dari rukuk", "Allah mendengar orang yang memuji-Nya. Ya Tuhan kami, segala puji bagi-Mu.", "Dibaca saat bangkit dari rukuk dan berdiri tegak.", "Siapa ucapannya bertepatan dengan ucapan para malaikat, diampuni dosanya yang telah lalu."),
        "dua_between_sajdas" to DuaText("Di antara dua sujud", "Ya Tuhanku, ampunilah aku, ya Tuhanku, ampunilah aku.", "Dibaca saat duduk di antara dua sujud.", "Doa duduk yang disunnahkan."),
        "dua_before_salam_four" to DuaText("Berlindung dari empat perkara sebelum salam", "Ya Allah, sesungguhnya aku berlindung kepada-Mu dari azab jahanam, dari azab kubur, dari fitnah kehidupan dan kematian, dan dari keburukan fitnah Al-Masih Dajjal.", "Dibaca setelah tasyahud akhir dan shalawat, sebelum salam.", "Nabi ﷺ memerintahkan untuk berlindung dari empat perkara ini."),
        "dua_qunoot_witr" to DuaText("Doa qunut dalam witir", "Ya Allah, berilah aku petunjuk sebagaimana orang yang telah Engkau beri petunjuk, berilah aku keselamatan sebagaimana orang yang telah Engkau beri keselamatan, uruslah aku sebagaimana orang yang telah Engkau urus, berkahilah untukku apa yang telah Engkau berikan, dan lindungilah aku dari keburukan apa yang telah Engkau tetapkan; sesungguhnya Engkau yang menetapkan dan tidak ditetapkan atas-Mu; sesungguhnya tidak akan hina orang yang Engkau lindungi; Mahaberkah Engkau ya Tuhan kami dan Mahatinggi.", "Dalam shalat witir — diajarkan Nabi ﷺ kepada Hasan bin Ali radhiyallahu anhu.", "Doa qunut yang disunnahkan dalam witir."),
        "dua_qunoot_hanafi" to DuaText("Doa qunut (Allahumma inna nasta'inuka)", "Ya Allah, sesungguhnya kami memohon pertolongan-Mu, memohon ampunan-Mu, beriman kepada-Mu, bertawakal kepada-Mu, dan memuji-Mu dengan segala kebaikan; kami bersyukur kepada-Mu dan tidak mengingkari-Mu, serta kami tinggalkan orang yang durhaka kepada-Mu. Ya Allah, hanya kepada-Mu kami beribadah, hanya untuk-Mu kami shalat dan sujud, hanya kepada-Mu kami berusaha dan bersegera, kami mengharap rahmat-Mu dan takut akan azab-Mu; sesungguhnya azab-Mu akan menimpa orang-orang kafir.", "Dalam witir — dibaca menurut mazhab Hanafi.", "Diriwayatkan dari Umar radhiyallahu anhu sebagai doa qunut."),
        "dua_sleep_aslamtu" to DuaText("Ucapan terakhir sebelum tidur", "Ya Allah, aku pasrahkan diriku kepada-Mu, aku serahkan urusanku kepada-Mu, aku sandarkan punggungku kepada-Mu, dengan penuh harap dan takut kepada-Mu; tiada tempat berlindung dan menyelamatkan diri dari-Mu kecuali kepada-Mu; aku beriman kepada kitab-Mu yang telah Engkau turunkan dan kepada nabi-Mu yang telah Engkau utus.", "Setelah berwudhu dan berbaring miring ke kanan — diucapkan terakhir.", "Jika ia wafat pada malam itu, ia wafat dalam keadaan fitrah."),
        "dua_waking_night" to DuaText("Saat terbangun di malam hari", "Tiada tuhan selain Allah semata, tiada sekutu bagi-Nya, milik-Nyalah kerajaan dan puji, Dia Mahakuasa atas segala sesuatu. Segala puji bagi Allah, Mahasuci Allah, tiada tuhan selain Allah, Allah Mahabesar, tiada daya dan kekuatan kecuali dengan Allah. Ya Allah, ampunilah aku.", "Dibaca saat terbangun di malam hari.", "Doanya dikabulkan; jika ia berwudhu dan shalat, shalatnya diterima."),
        "dua_hamm_ibn_masud" to DuaText("Doa kesedihan (riwayat Ibnu Mas'ud)", "Ya Allah, sesungguhnya aku adalah hamba-Mu, anak hamba-Mu, anak hamba perempuan-Mu, ubun-ubunku berada di tangan-Mu, berlaku atasku ketetapan-Mu, adil bagiku keputusan-Mu. Aku memohon kepada-Mu dengan setiap nama yang menjadi milik-Mu, yang Engkau namakan diri-Mu dengannya, atau Engkau turunkan dalam kitab-Mu, atau Engkau ajarkan kepada salah satu makhluk-Mu, atau Engkau simpan dalam ilmu gaib di sisi-Mu, agar Engkau jadikan Al-Qur'an sebagai penyejuk hatiku, cahaya dadaku, penghilang kesedihanku, dan pelenyap kegundahanku.", "Saat kesedihan dan kegundahan — Allah menggantinya dengan kegembiraan.", "Allah menghilangkan kesedihan dan kegundahannya serta menggantinya dengan kegembiraan."),
        "dua_difficulty_sahl" to DuaText("Saat menghadapi kesulitan", "Ya Allah, tiada kemudahan kecuali apa yang Engkau jadikan mudah, dan Engkau jadikan kesulitan itu mudah jika Engkau kehendaki.", "Dibaca saat menghadapi suatu kesulitan.", "Untuk memudahkan ujian dan perkara-perkara yang sulit."),
        "dua_musibah" to DuaText("Saat tertimpa musibah (Istirja')", "Sesungguhnya kami milik Allah dan sesungguhnya kepada-Nya kami kembali. Ya Allah, berilah aku pahala atas musibahku dan gantilah untukku dengan yang lebih baik darinya.", "Dibaca saat mengalami kehilangan atau musibah apa pun.", "Allah akan menggantinya dengan yang lebih baik — sebagaimana terjadi pada Ummu Salamah radhiyallahu anha."),
        "dua_debt" to DuaText("Terbebas dari hutang", "Ya Allah, cukupkanlah aku dengan yang halal dari-Mu sehingga aku tidak membutuhkan yang haram, dan cukupkanlah aku dengan karunia-Mu dari selain-Mu.", "Untuk melunasi hutang — diajarkan Nabi ﷺ kepada Ali radhiyallahu anhu.", "Meskipun hutangnya sebesar gunung, Allah akan melunasinya."),
        "dua_anger" to DuaText("Saat marah", "Aku berlindung kepada Allah dari setan yang terkutuk.", "Dibaca saat marah.", "Nabi ﷺ bersabda: jika ia mengucapkannya, kemarahannya akan reda."),
        "dua_waswasa" to DuaText("Melawan bisikan keraguan iman", "Aku beriman kepada Allah dan rasul-rasul-Nya.", "Saat setan membisikkan keraguan dalam iman.", "Mengucapkannya lalu berhenti memikirkan bisikan tersebut."),
        "dua_travel_full" to DuaText("Doa perjalanan lengkap", "Ya Allah, sesungguhnya kami memohon kepada-Mu dalam perjalanan kami ini kebaikan dan ketakwaan, serta amal yang Engkau ridhai. Ya Allah, mudahkanlah perjalanan kami ini dan lipatlah jaraknya untuk kami. Ya Allah, Engkaulah teman dalam perjalanan dan pengganti bagi keluarga yang ditinggalkan.", "Dibaca saat memulai perjalanan setelah 'subhanalladzi sakhkhara'.", "Doa perjalanan lengkap yang disunnahkan."),
        "dua_return_travel" to DuaText("Saat kembali dari perjalanan", "Kami kembali, bertaubat, beribadah, dan memuji Tuhan kami.", "Dibaca saat kembali dari perjalanan.", "Nabi ﷺ membacanya saat kembali dari perjalanan."),
        "dua_farewell_traveller" to DuaText("Mengucapkan selamat jalan kepada musafir", "Aku titipkan agamamu, amanahmu, dan penutup amalmu kepada Allah.", "Diucapkan saat melepas kepergian seorang musafir.", "Apa yang dititipkan kepada Allah tidak akan hilang."),
        "dua_entering_town" to DuaText("Singgah di tempat baru", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari keburukan apa yang Dia ciptakan.", "Dibaca saat singgah di suatu tempat atau kota baru.", "Tidak ada sesuatu pun yang membahayakannya hingga ia pergi dari tempat itu."),
        "dua_boarding_ship" to DuaText("Saat menaiki kapal", "Dengan nama Allah saat berlayar dan berlabuhnya, sesungguhnya Tuhanku Maha Pengampun lagi Maha Penyayang.", "Dibaca saat menaiki kapal — ucapan Nabi Nuh alaihissalam.", "Ayat Al-Qur'an — doa kapal Nabi Nuh alaihissalam."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar dengan Al-Hayyul Qayyum", "Aku memohon ampun kepada Allah yang tiada tuhan selain Dia, Yang Mahahidup lagi terus-menerus mengurus makhluk-Nya, dan aku bertaubat kepada-Nya.", "Untuk memohon taubat.", "Dosa-dosanya diampuni meskipun ia telah lari dari medan perang."),
        "dua_rabbighfir_warham" to DuaText("Ya Tuhanku, ampunilah dan rahmatilah", "Ya Tuhanku, ampunilah dan berilah rahmat, dan Engkau adalah sebaik-baik Pemberi rahmat.", "Doa ampunan dan rahmat dalam Al-Qur'an.", "Ayat terakhir surah Al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kafarat majelis", "Mahasuci Engkau ya Allah, dan dengan memuji-Mu, aku bersaksi tiada tuhan selain Engkau, aku memohon ampun kepada-Mu dan bertaubat kepada-Mu.", "Dibaca saat beranjak dari suatu majelis.", "Penebus dosa atas hal-hal sia-sia yang terjadi dalam majelis."),
        "dua_jami_forgiveness" to DuaText("Doa ampunan yang menyeluruh", "Ya Allah, ampunilah kesalahanku, kebodohanku, dan sikap berlebihanku dalam urusanku, serta apa yang lebih Engkau ketahui daripada aku.", "Doa menyeluruh yang sering dibaca Nabi ﷺ.", "Doa lengkap yang sering diucapkan Nabi ﷺ."),
        "dua_parents_nuh" to DuaText("Doa Nabi Nuh untuk orang tua", "Ya Tuhanku, ampunilah aku, kedua orang tuaku, orang yang masuk ke rumahku dalam keadaan beriman, serta seluruh orang-orang mukmin laki-laki dan perempuan.", "Untuk orang tua dan orang-orang beriman.", "Doa Nabi Nuh alaihissalam."),
        "dua_shukr_parents" to DuaText("Syukur atas nikmat orang tua dan keturunan saleh", "Ya Tuhanku, berilah aku petunjuk untuk mensyukuri nikmat-Mu yang telah Engkau anugerahkan kepadaku dan kepada kedua orang tuaku, dan agar aku dapat berbuat amal saleh yang Engkau ridhai; berilah kebaikan kepadaku pada keturunanku; sesungguhnya aku bertaubat kepada-Mu dan sesungguhnya aku termasuk orang-orang yang berserah diri.", "Doa Al-Qur'an bagi yang telah mencapai usia empat puluh tahun.", "Menggabungkan syukur nikmat, amal saleh, dan perbaikan keturunan dalam satu doa."),
        "dua_intimacy" to DuaText("Sebelum bersuami istri", "Dengan nama Allah. Ya Allah, jauhkanlah kami dari setan dan jauhkanlah setan dari apa yang Engkau rezekikan kepada kami.", "Dibaca sebelum suami istri bersama.", "Jika ditakdirkan lahir anak dari hubungan itu, setan tidak akan pernah dapat mencelakainya."),
        "dua_ibrahim_children_protection" to DuaText("Menjaga negeri dan keturunan", "Ya Tuhanku, jadikanlah negeri ini negeri yang aman, dan jauhkanlah aku beserta anak cucuku dari menyembah berhala.", "Doa Nabi Ibrahim alaihissalam untuk negeri dan keturunannya.", "Doa keteguhan di atas tauhid."),
        "dua_drinking_milk" to DuaText("Saat minum susu", "Ya Allah, berkahilah kami padanya dan tambahkanlah untuk kami darinya.", "Dibaca saat minum susu.", "Susu mencukupi sebagai makanan sekaligus minuman."),
        "dua_iftar_host" to DuaText("Berbuka puasa di rumah orang lain", "Orang-orang yang berpuasa telah berbuka di tempat kalian, orang-orang yang baik telah menyantap makanan kalian, dan para malaikat telah mendoakan kalian.", "Dibaca saat berbuka puasa di rumah orang lain.", "Doa Nabi ﷺ untuk tuan rumah."),
        "dua_seeing_first_fruit" to DuaText("Melihat buah pertama musim", "Ya Allah, berkahilah kami pada buah-buahan kami, berkahilah kami pada kota kami, berkahilah kami pada sha' kami, dan berkahilah kami pada mudd kami.", "Dibaca saat melihat buah pertama musim itu.", "Doa keberkahan rezeki dan negeri."),
        "dua_good_news" to DuaText("Saat mendengar kabar gembira", "Segala puji bagi Allah yang dengan nikmat-Nya amal-amal saleh menjadi sempurna.", "Saat mendengar kabar gembira (dan sujud syukur).", "Nabi ﷺ mengucapkannya saat melihat sesuatu yang menyenangkannya."),
        "dua_looking_mirror" to DuaText("Saat bercermin", "Ya Allah, sebagaimana Engkau perindah rupaku, maka perindahlah akhlakku.", "Dibaca saat bercermin.", "Nabi ﷺ membaca doa ini."),
        "dua_rabbana_taqabbal" to DuaText("Diterimanya amal", "Ya Tuhan kami, terimalah dari kami, sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui. Dan terimalah taubat kami, sesungguhnya Engkaulah Yang Maha Penerima taubat lagi Maha Penyayang.", "Doa Nabi Ibrahim dan Ismail alaihimassalam saat membangun Kakbah.", "Doa memohon diterimanya amal saleh setelah menyelesaikannya."),
    )
}
